insert into public.pantheons (id,name,book,status,theme,rules,sort) values ($q$greek$q$,$q$Greek$q$,$q$From Hearth to Ecstasy$q$,$q$ready$q$,null,$q${"first":"hestia","low":["hades"]}$q$::jsonb,0) on conflict (id) do update set name=excluded.name, book=excluded.book, status=excluded.status, theme=excluded.theme, rules=excluded.rules, sort=excluded.sort;
insert into public.pantheon_texts values ($q$greek$q$,$q$Hestia first, Hestia last. The book records the ancient custom of giving Hestia the first and last portion of every offering, to any god, so her share opens and closes the rite.$q$,$q$Keep Hades's objects somewhere low rather than at eye level. The book notes ancient chthonic rites used honey rather than wine, turned palms toward the earth, and avoided incense, whose smoke rises.$q$) on conflict (pantheon_id) do update set first_text=excluded.first_text, low_text=excluded.low_text;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$hestia$q$,$q$greek$q$,$q$Hestia$q$,1,$q$HESS-tee-uh$q$,$q$Hearth and home$q$,$q$Hearth, home, the fire of family and state$q$,$q$Donkey$q$,$q$None well attested in ancient sources$q$,$q$The hearth fire itself; a seated, veiled figure$q$,$q$The safety and continuity of the household: a fire that kept burning, a family fed and sheltered$q$,array[$q$home$q$,$q$nourish$q$]::text[],$q$greek/hestia.png$q$,0) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$hestia$q$,$q$The hearth. The first fire. The need that comes before every other need.$q$,$q$A single unbroken circle with a small flame at its center. Draw it by hand, imperfectly. It's meant to look kept, not crafted.$q$,$q$Say the invocation once, out loud or silently, before you cook or before everyone sits down to eat.$q$,$q$Hestia, first and last, keeper of the flame that does not travel, teach me the stillness at the center of the turning. Let what I tend outlast what I chase.$q$,$q$[{"t":"A candle, lit at the start of a meal or a gathering and blown out at its end","g":"candle"}]$q$::jsonb,$q$A small, permanent space, not one assembled and dismantled for ritual, but a corner that stays. No elaborate décor; Hestia's whole character is restraint.$q$,$q$["Light the candle at the start of a meal or gathering and blow it out at its end.","Leave the corner in place between practices. It is meant to stay."]$q$::jsonb,$q${"t":"The hearth fire itself, or a seated, veiled figure","g":"figure"}$q$::jsonb,$q${"quick":"What in your life functions like Hestia's hearth: the constant, unglamorous thing that everything else is built around, and that you rarely think to thank? What would it cost you if it went out?","deeper":"Where in your life have you mistaken quiet, sustaining work for something unimportant, simply because it never asked for credit or attention?"}$q$::jsonb,$q${"text":"For without you mortals hold no banquet, where one does not duly pour sweet wine in offering to Hestia both first and last.","src":"Homeric Hymn 29, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Noumenia","when":"First day of every lunar month","m":-1},{"n":"Amphidromia","when":"Fifth or seventh day after a birth","m":null}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$demeter$q$,$q$greek$q$,$q$Demeter$q$,2,$q$dih-MEE-ter$q$,$q$Harvest and grain$q$,$q$Harvest, cultivated grain, fertility of the earth$q$,$q$Pig$q$,$q$Wheat and barley; poppy$q$,$q$Sheaf of wheat, cornucopia, torch$q$,$q$A good harvest, protection from famine, fertility of the land, fertility of their own bodies$q$,array[$q$nourish$q$,$q$endings$q$]::text[],$q$greek/demeter.png$q$,1) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$demeter$q$,$q$Demeter is the fear that this year's harvest might be the last one.$q$,$q$A single stalk of wheat, drawn as a straight line with a few short strokes branching off it, set inside an unbroken circle. Draw the grain heads uneven.$q$,$q$Before you eat bread today, break off a small piece and set it aside rather than eating it.$q$,$q$Demeter, who gives and who withholds, teach me that grief and growth share a root. What I have lost, let it feed what comes next. What I am given, let me not take for granted.$q$,$q$[{"t":"A small dish for grain, seeds, or a piece of bread","g":"dish"}]$q$::jsonb,$q$If you cook or garden at all, this is an easy one to fold into something you already do.$q$,$q$["Replace the grain or bread regularly rather than leaving it to go stale."]$q$::jsonb,$q${"t":"A sheaf of wheat, a cornucopia or a torch; poppies","g":"branch"}$q$::jsonb,$q${"quick":"What have you had to let go of in order for something else to grow?","deeper":"Demeter's grief was not gentle. It stopped the harvest of an entire world. Where in your life have you underestimated how much room real grief needs, or tried to keep producing through it anyway?"}$q$::jsonb,$q${"text":"Lady, giver of good gifts, bringer of seasons, queen Deo, be gracious, you and your daughter all beauteous Persephone.","src":"Homeric Hymn to Demeter, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Eleusinian Mysteries","when":"September (Boedromion)","m":8},{"n":"Thesmophoria","when":"Mid-to-late October (Pyanepsion)","m":9}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$poseidon$q$,$q$greek$q$,$q$Poseidon$q$,3,$q$poh-SY-dun$q$,$q$Sea, earthquake, horses$q$,$q$The sea, earthquakes, horses$q$,$q$Horse, bull, dolphin$q$,$q$None specifically his; the olive belongs to Athena$q$,$q$Trident$q$,$q$Safe passage across water, protection from shipwreck and earthquakes, strong horses$q$,array[$q$passage$q$]::text[],$q$greek/poseidon.png$q$,2) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$poseidon$q$,$q$The ground itself can fail too, and so can the sea that feeds you and drowns you in the same afternoon.$q$,$q$A trident: one straight shaft, three curved tines, a crossbar near the base, inside an unbroken circle. Let the tines be uneven if your hand isn't steady.$q$,$q$Before you do something you can't fully control the outcome of, a trip, a decision, a conversation, say a short line of your own asking for safe passage.$q$,$q$Poseidon, whose ground moves and whose sea does not hold still, I don't ask you to calm anything. I ask for steadiness enough to move through what I can't control, and the sense to respect what I can't.$q$,$q$[{"t":"A small dish of salt water, changed regularly","g":"dish"},{"t":"Or a smooth stone taken from a shoreline","g":"stone"},{"t":"Anything with a horse motif you already keep","g":"figure"}]$q$::jsonb,null,$q$["Change the salt water regularly."]$q$::jsonb,$q${"t":"A trident; a horse, bull or dolphin","g":"figure"}$q$::jsonb,$q${"quick":"What in your life right now feels like weather: real, powerful, and completely outside your control?","deeper":"Poseidon lost the contest for Athens and, by most accounts, did not lose it well. Where have you responded badly to being passed over, and what would it have looked like to lose with more grace than he did?"}$q$::jsonb,$q${"text":"Hail, Poseidon, Holder of the Earth, dark-haired lord! O blessed one, be kindly in heart and help those who voyage in ships!","src":"Homeric Hymn 22, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Poseidea","when":"8th of Poseideon, mid-December to mid-January","m":11},{"n":"Isthmian Games","when":"Spring, every two years","m":3}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$zeus$q$,$q$greek$q$,$q$Zeus$q$,4,$q$zoos$q$,$q$Sky, law, oaths$q$,$q$The sky, weather, law, oaths, kingship$q$,$q$Eagle, bull$q$,$q$Oak$q$,$q$Thunderbolt, aegis$q$,$q$Justice, enforcement of oaths, protection for travelers and guests, favorable weather, legitimacy for rulers$q$,array[$q$promise$q$,$q$passage$q$]::text[],$q$greek/zeus.png$q$,3) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$zeus$q$,$q$Someone had to be in charge of all of it, or none of it made sense.$q$,$q$A thunderbolt, drawn as one jagged zigzag stroke, inside an unbroken circle. Keep the angles sharp and a little uneven. It should look struck, not stenciled.$q$,$q$When you make a promise today, however small, pause and actually mean it before you say it.$q$,$q$Zeus, who holds the sky over everything else, I don't ask you to make my choices for me. I ask for the clarity to keep the commitments I make, and the humility to answer for the ones I break.$q$,$q$[{"t":"An oak leaf or an acorn","g":"leaf"},{"t":"Or a small object that stands for a promise you're currently keeping","g":"ring"}]$q$::jsonb,$q$Nothing elaborate. What matters is that it's honest.$q$,$q$["Keep it honest: if the promise it stands for ends, let the object change with it."]$q$::jsonb,$q${"t":"An eagle; oak; a thunderbolt","g":"figure"}$q$::jsonb,$q${"quick":"What's one commitment in your life right now that you've been treating more casually than you should?","deeper":"Zeus enforced oaths in others while breaking plenty of his own, particularly to Hera. Where in your life do you hold other people to a standard you don't fully hold yourself to?"}$q$::jsonb,$q${"text":"I will sing of Zeus, chiefest among the gods and greatest, all-seeing, the lord of all.","src":"Homeric Hymn 23, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Olympic Games","when":"Late August or early September, every four years","m":7}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$hera$q$,$q$greek$q$,$q$Hera$q$,5,$q$HAIR-uh$q$,$q$Marriage and family$q$,$q$Marriage, women, family, childbirth$q$,$q$Cow; the peacock is a later, largely Roman association$q$,$q$Pomegranate$q$,$q$Diadem or crown, scepter$q$,$q$Legitimacy and protection in marriage, safe childbirth, household stability, justice against betrayal$q$,array[$q$promise$q$,$q$love$q$,$q$home$q$]::text[],$q$greek/hera.png$q$,4) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$hera$q$,$q$Once someone is in charge, the next question is who they're bound to, and what holds that bond together.$q$,$q$A crown, drawn as three peaks over a straight base line, inside an unbroken circle. Keep the peaks slightly uneven. Authority that's earned looks a little worn.$q$,$q$Name one relationship in your life, romantic or not, and do one small, concrete thing today to honor what you've actually committed to it.$q$,$q$Hera, who is owed more than a feeling, I ask for the clarity to see what my commitments actually require of me, and the steadiness to give it even on the days it isn't easy.$q$,$q$[{"t":"A pomegranate, fresh or a small carved or painted one","g":"fruit"},{"t":"Or a plain band or ring that represents a commitment you keep","g":"ring"}]$q$::jsonb,$q$Nothing needs to be elaborate or bought for this.$q$,$q$["Replace a fresh pomegranate before it spoils, or keep a carved or painted one."]$q$::jsonb,$q${"t":"A crown or diadem, a scepter; a cow","g":"figure"}$q$::jsonb,$q${"quick":"Where in your life are you offering feeling without follow-through, the sentiment of commitment without its substance?","deeper":"Hera is often reduced to her jealousy, but her myths are just as much about what a broken vow costs everyone around it. Where has someone else's broken commitment shaped your life, and how has that shaped what you expect from your own?"}$q$::jsonb,$q${"text":"I sing of golden-throned Hera whom Rhea bare. Queen of the immortals is she, surpassing all in beauty.","src":"Homeric Hymn 12, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Heraean Games","when":"At Olympia, every four years","m":null},{"n":"Daedala","when":"Plataea, roughly every four years; the Greater every sixty","m":null}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$hades$q$,$q$greek$q$,$q$Hades$q$,6,$q$HAY-deez$q$,$q$The underworld$q$,$q$The underworld and the dead; buried wealth and minerals as Plouton$q$,$q$Cerberus, his own hound$q$,$q$Cypress, narcissus$q$,$q$Key, cornucopia (as Plouton)$q$,$q$Rarely petitioned directly; more often placated or avoided$q$,array[$q$endings$q$]::text[],$q$greek/hades.png$q$,5) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$hades$q$,$q$Someone has to govern what's on the other side, or it stays a formless kind of fear instead of a place with rules.$q$,$q$A key: a small circle for the bow, a straight shaft, one or two teeth at the base, inside an unbroken circle. It should look like it locks something, not like it opens something.$q$,$q$Name, silently or aloud, one thing you're avoiding thinking about because it involves an ending. Don't solve it. Just name it.$q$,$q$Hades, who governs what I can't undo and can't outrun, I don't ask you to spare me from endings. I ask for the honesty to face the ones already in front of me, instead of pretending they're not there.$q$,$q$[{"t":"A single dark stone","g":"stone"},{"t":"A cypress sprig, if you can find one","g":"branch"},{"t":"Or a key that no longer opens anything you own","g":"key"}]$q$::jsonb,null,$q$["Keep it low, below eye level."]$q$::jsonb,$q${"t":"Narcissus; a cornucopia for Hades as Plouton","g":"branch"}$q$::jsonb,$q${"quick":"What ending in your life are you currently pretending isn't coming?","deeper":"Hades is often the most feared god and, in the actual myths, one of the least cruel. Where in your life have you let fear of a thing stand in for an honest look at what the thing actually is?"}$q$::jsonb,$q${"text":"Go now, Persephone, to your dark-robed mother, go, and feel kindly in your heart towards me.","src":"Hades, in the Homeric Hymn to Demeter, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Chthonic rites","when":"No fixed festival; whenever the situation called for them","m":null}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$ares$q$,$q$greek$q$,$q$Ares$q$,7,$q$AIR-eez$q$,$q$War's raw force$q$,$q$War, its violence and chaos rather than strategy$q$,$q$Vulture, dog, boar$q$,$q$None specifically his$q$,$q$Spear, helmet, shield$q$,$q$Raw battle-courage or ferocity for a specific coming fight$q$,array[$q$anger$q$]::text[],$q$greek/ares.png$q$,6) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$ares$q$,$q$Some of it people bring on each other, on purpose, right now, and that has to be reckoned with separately.$q$,$q$A spear: a single shaft with a simple triangular point and a short crossbar near the base, inside an unbroken circle. Keep it plain.$q$,$q$Before you respond to whatever's provoking you today, take one breath longer than feels necessary.$q$,$q$Ares, whose fury I recognize in myself sometimes, I don't ask you to make me fiercer. I ask for the discipline to use whatever anger I'm carrying instead of being used by it.$q$,$q$[{"t":"Something plain and unglamorous: a stone, a nail, a scrap of iron","g":"tool"}]$q$::jsonb,$q$Nothing meant to look impressive. This isn't a god who responds to decoration.$q$,$q$["Keep it plain. Don't add decoration."]$q$::jsonb,$q${"t":"A spear, helmet or shield, plain military gear","g":"tool"}$q$::jsonb,$q${"quick":"Where in your life has raw force, anger, or aggression gotten you further, or cost you more, than a more strategic response would have?","deeper":"Ares was distrusted even by his own family, in part because his violence had no strategy behind it. Where in your own conflicts are you all force and no plan?"}$q$::jsonb,$q${"text":"Give you me boldness to abide within the harmless laws of peace, avoiding strife and hatred.","src":"Homeric Hymn 8 (authorship disputed), trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Ares Gynaecothoenas","when":"No fixed date; a local Tegean cult","m":null}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$athena$q$,$q$greek$q$,$q$Athena$q$,8,$q$uh-THEE-nuh$q$,$q$Wisdom and strategy$q$,$q$Wisdom, strategic warfare, civic order, craft$q$,$q$Owl, serpent$q$,$q$Olive tree$q$,$q$Aegis, gorgoneion, spear$q$,$q$Wisdom in judgment and counsel, protection for the city, skill in craft and weaving, victory through strategy$q$,array[$q$decide$q$,$q$craft$q$,$q$anger$q$]::text[],$q$greek/athena.png$q$,7) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$athena$q$,$q$Someone has to think ahead, plan the defense before the attack, and know when not to fight at all.$q$,$q$An owl's face: two round eyes, a small triangular beak, and two short tufts at the top like ears, inside an unbroken circle. Keep the eyes wide and steady.$q$,$q$Before reacting to a problem today, ask yourself what the smartest response would be, not just the fastest one. Then take a breath and do that instead.$q$,$q$Athena, whose strength is in her thinking, I don't ask you to fight my battles. I ask for the clarity to see the whole board before I make my move.$q$,$q$[{"t":"An olive branch or a small dish of olive oil","g":"branch"},{"t":"Something that represents a skill you're actively building","g":"tool"},{"t":"A small owl figure, if you have one","g":"figure"}]$q$::jsonb,null,$q$["Keep the object for your skill current with what you're actually building."]$q$::jsonb,$q${"t":"An owl; olive; the aegis or gorgoneion","g":"figure"}$q$::jsonb,$q${"quick":"What decision in your life right now would benefit from more strategy and less speed?","deeper":"Athena couldn't tolerate being outdone by Arachne, a mortal with no claim to divine status. Where in your own life does your competence turn into a need to always be the best in the room?"}$q$::jsonb,$q${"text":"I begin to sing of Pallas Athene, the glorious goddess, bright-eyed, inventive, unbending of heart.","src":"Homeric Hymn 28, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Panathenaea","when":"28th of Hekatombaion, roughly midsummer","m":6},{"n":"Arrhephoria","when":"Annually, date uncertain","m":null}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$hephaestus$q$,$q$greek$q$,$q$Hephaestus$q$,9,$q$heh-FES-tuss$q$,$q$Fire and the forge$q$,$q$Fire, metalworking, craft$q$,$q$None specifically his$q$,$q$None specifically his$q$,$q$Hammer, anvil, tongs$q$,$q$Skill and success in craftsmanship, protection for artisans, competence in making things well$q$,array[$q$craft$q$]::text[],$q$greek/hephaestus.png$q$,8) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$hephaestus$q$,$q$Wisdom can plan the city. It still needs someone to build the walls and forge the tools.$q$,$q$A hammer: a rectangular head over a straight handle, inside an unbroken circle. Keep the proportions a little heavy. This is a working tool, not a decoration.$q$,$q$Take one thing today that's half-finished and do the next concrete step on it.$q$,$q$Hephaestus, who works with what's actually in front of him, I don't ask for talent I don't have. I ask for the patience to keep making things well, even the parts nobody applauds.$q$,$q$[{"t":"A small tool you actually use: a hand tool, a needle, whatever fits your own craft","g":"tool"}]$q$::jsonb,$q$Kept somewhere visible rather than put away.$q$,$q$["Keep the tool visible rather than put away, and keep using it."]$q$::jsonb,$q${"t":"A hammer, anvil or tongs","g":"tool"}$q$::jsonb,$q${"quick":"What's something in your life you've been avoiding simply because it requires unglamorous, repetitive effort?","deeper":"Hephaestus was mocked by other gods for his appearance and, in the Chalceia, effectively erased from his own festival. Where have you kept contributing real value to something that didn't credit you for it, and how do you feel about that now?"}$q$::jsonb,$q${"text":"Be gracious, Hephaestus, and grant me success and prosperity!","src":"Homeric Hymn 20, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Hephaesteia","when":"Spring, in Athens","m":3},{"n":"Chalceia","when":"Last day of Pyanepsion, late October","m":9}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$apollo$q$,$q$greek$q$,$q$Apollo$q$,10,$q$uh-POL-oh$q$,$q$Prophecy, music, healing$q$,$q$Prophecy, music and poetry, healing, archery; later, the sun$q$,$q$Raven, swan$q$,$q$Laurel$q$,$q$Lyre, bow$q$,$q$Guidance and prophecy, healing from illness, success in music and poetry$q$,array[$q$healing$q$,$q$decide$q$]::text[],$q$greek/apollo.png$q$,9) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$apollo$q$,$q$Someone who can heal what's broken and say what's coming before it arrives.$q$,$q$A lyre: two curved arms rising from a shallow base, with three strings between them, inside an unbroken circle. Keep the curves loose rather than mechanical.$q$,$q$Ask yourself one honest question about something you've been avoiding looking at clearly, and sit with the answer for a moment, even if you don't act on it yet.$q$,$q$Apollo, who sees further than the moment I'm standing in, I don't ask you to tell me the future. I ask for the clarity to see my present situation as it actually is.$q$,$q$[{"t":"A laurel leaf","g":"leaf"},{"t":"A small musical instrument or a guitar pick","g":"figure"},{"t":"Or anything connected to a healing practice you maintain","g":"jar"}]$q$::jsonb,null,$q$[]$q$::jsonb,$q${"t":"A lyre or bow; a raven or swan","g":"figure"}$q$::jsonb,$q${"quick":"What's one area of your life where you'd rather stay vague than get a clear, possibly uncomfortable answer?","deeper":"The Pythia's words needed priests to interpret them before anyone could act on them. Where in your own life are you relying on someone else to interpret a truth you could look at directly yourself?"}$q$::jsonb,$q${"text":"I will remember and not be unmindful of Apollo who shoots afar.","src":"Homeric Hymn 3, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Delphic Oracle","when":"Once a month, nine months of the year","m":-1},{"n":"Pythian Games","when":"At Delphi, every four years","m":null}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$artemis$q$,$q$greek$q$,$q$Artemis$q$,11,$q$AR-teh-miss$q$,$q$The wild and its edges$q$,$q$Wilderness, the hunt, wild animals, transitions to adulthood, childbirth$q$,$q$Deer$q$,$q$Cypress$q$,$q$Bow and arrow; the crescent moon is a later association$q$,$q$Protection for young women approaching marriage and childbirth, success in hunting, protection of wild places, safe transitions$q$,array[$q$threshold$q$]::text[],$q$greek/artemis.png$q$,10) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$artemis$q$,$q$Someone else has to guard the edges: the wild places, the threshold nobody's watching.$q$,$q$A bow: a single curved arc with a straight bowstring, an arrow nocked and pointing outward, inside an unbroken circle. Let the curve be slightly uneven.$q$,$q$Spend two minutes outside today, actually looking at something wild or growing rather than passing by it.$q$,$q$Artemis, who guards the edges of things, I don't ask you to keep me from every risk. I ask for the instinct to know which wild places in my life are worth entering, and which ones aren't.$q$,$q$[{"t":"A dried leaf or small branch gathered outdoors","g":"leaf"},{"t":"An arrowhead-shaped stone","g":"stone"},{"t":"Or a small carved deer","g":"figure"}]$q$::jsonb,null,$q$["Gather the leaf or branch outdoors yourself, and replace it when you go out again."]$q$::jsonb,$q${"t":"A bow and arrow; a deer; cypress","g":"figure"}$q$::jsonb,$q${"quick":"What edge or threshold in your life are you standing at right now without fully admitting it?","deeper":"Actaeon's punishment for accidentally seeing something forbidden was total and immediate. Where in your own life have you judged someone else's mistake more harshly than you'd judge the same mistake in yourself?"}$q$::jsonb,$q${"text":"Muse, sing of Artemis, sister of the Far-shooter, the virgin who delights in arrows.","src":"Homeric Hymn 9, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Brauronia and Arkteia","when":"At Brauron, roughly every four years","m":null},{"n":"Artemis Orthia","when":"Annually, at Sparta","m":null}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$aphrodite$q$,$q$greek$q$,$q$Aphrodite$q$,12,$q$af-roh-DY-tee$q$,$q$Love and desire$q$,$q$Love, desire, beauty, social cohesion$q$,$q$Dove, sparrow$q$,$q$Myrtle, rose$q$,$q$The kestos (girdle), seashell$q$,$q$Success in romantic love, beauty and desirability, social harmony, fertility in a broader sense$q$,array[$q$love$q$]::text[],$q$greek/aphrodite.png$q$,11) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$aphrodite$q$,$q$A city still needs a reason to want to keep living at all, some pull toward another person.$q$,$q$A scallop shell: a rounded fan of simple radiating lines inside a curved outline, inside an unbroken circle. Keep the lines a little irregular, like something the sea actually shaped.$q$,$q$Tell someone you care about, in one direct sentence, something specific you appreciate about them.$q$,$q$Aphrodite, who makes connection worth the risk it always carries, I don't ask you to make me irresistible. I ask for the courage to be genuinely seen by someone else.$q$,$q$[{"t":"A seashell","g":"shell"},{"t":"A small mirror","g":"ring"},{"t":"Or fresh flowers, changed regularly","g":"branch"}]$q$::jsonb,null,$q$["Change the flowers regularly."]$q$::jsonb,$q${"t":"A dove; myrtle or roses","g":"branch"}$q$::jsonb,$q${"quick":"Where in your life have you been withholding real affection out of fear of how it might be received?","deeper":"Aphrodite's affair with Ares became a public spectacle when Hephaestus exposed it. Where in your own relationships has private vulnerability been made public in a way that still stings to think about?"}$q$::jsonb,$q${"text":"Muse, tell me the deeds of golden Aphrodite the Cyprian, who stirs up sweet passion in the gods.","src":"Homeric Hymn 5, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Aphrodisia","when":"Hekatombaion, mid-July to mid-August","m":6}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$hermes$q$,$q$greek$q$,$q$Hermes$q$,13,$q$HER-meez$q$,$q$Boundaries and travel$q$,$q$Boundaries, travel, communication, trade, guiding the dead$q$,$q$Tortoise, rooster$q$,$q$None specifically his$q$,$q$Caduceus, winged sandals, traveler's hat$q$,$q$Safe travel and passage across boundaries, success in trade, eloquence in negotiation, safe conduct for the dead$q$,array[$q$passage$q$,$q$threshold$q$]::text[],$q$greek/hermes.png$q$,12) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$hermes$q$,$q$Something still has to carry the message between them, and between every other boundary a person crosses.$q$,$q$A staff with two winged tips at the top and two serpents winding around its length, inside an unbroken circle. Keep the coils loose and overlapping.$q$,$q$Before you cross a threshold today, literal or otherwise, a doorway, a decision, a difficult conversation, pause for one breath and notice that you're crossing it.$q$,$q$Hermes, who moves between places I can't move between myself, I don't ask you to make the crossing easy. I ask for the wit to handle whatever's on the other side.$q$,$q$[{"t":"A small stone from a crossroads or a journey","g":"stone"},{"t":"Or a well-worn traveling item: a set of keys, a compass, a pair of shoes kept for that purpose","g":"key"}]$q$::jsonb,null,$q$[]$q$::jsonb,$q${"t":"A caduceus, winged sandals or a traveler's hat","g":"figure"}$q$::jsonb,$q${"quick":"What boundary or threshold in your life are you standing at right now without fully crossing it?","deeper":"Hermes talked his way out of serious consequences for theft on the day he was born. Where in your own life has charm or cleverness let you avoid a reckoning you probably needed?"}$q$::jsonb,$q${"text":"Muse, sing of Hermes, the son of Zeus and Maia, the luck-bringing messenger of the immortals.","src":"Homeric Hymn 4, trans. Evelyn-White"}$q$::jsonb,$q$[{"n":"Hermaea","when":"Many places, no single date","m":null}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.deities (id,pantheon_id,name,chapter,pronunciation,short,domain,animal,plant,symbol,asked_for,needs,sigil_path,sort) values ($q$dionysus$q$,$q$greek$q$,$q$Dionysus$q$,14,$q$dee-oh-NY-sos$q$,$q$Wine, theater, ecstasy$q$,$q$Wine, ecstasy, theater, ritual madness, the vine$q$,$q$Panther, leopard, bull$q$,$q$Grapevine, ivy$q$,$q$Thyrsus, kantharos (wine cup)$q$,$q$Release from ordinary self-control, a good vintage, protection for actors and playwrights, ecstatic communion$q$,array[$q$release$q$]::text[],$q$greek/dionysus.png$q$,13) on conflict (id) do update set name=excluded.name, chapter=excluded.chapter, pronunciation=excluded.pronunciation, short=excluded.short, domain=excluded.domain, animal=excluded.animal, plant=excluded.plant, symbol=excluded.symbol, asked_for=excluded.asked_for, needs=excluded.needs, sigil_path=excluded.sigil_path, sort=excluded.sort;
insert into public.deity_content values ($q$dionysus$q$,$q$Wine, ecstasy, theater, and the dissolving of ordinary boundaries all answered to him.$q$,$q$A fennel staff crowned with a pinecone, wound with curling ivy tendrils along its length, set inside an unbroken circle.$q$,$q$Before you eat or drink something today, pause for one breath and let yourself actually taste it, rather than consuming it on autopilot.$q$,$q$Dionysus, who loosens what holds too tight, I don't ask you to take away my judgment. I ask for one evening where I don't need it — and the sense to know when that evening is over.$q$,$q$[{"t":"A cluster of grapes or a small glass of wine (or grape juice)","g":"cup"},{"t":"A sprig of ivy","g":"leaf"},{"t":"A ticket stub or program from a play, concert, or other live performance, kept for that purpose","g":"card"}]$q$::jsonb,null,$q$["Replace grapes or wine before they turn."]$q$::jsonb,$q${"t":"A thyrsus; a kantharos; a panther or leopard","g":"figure"}$q$::jsonb,$q${"quick":"Where in your life could you use a sanctioned, structured release rather than the unstructured kind you're currently taking?","deeper":"Dionysus is remembered by name and myth; Hestia, arguably more faithfully served, is remembered by absence. What in your own life gets the least credit precisely because it's the most constant?"}$q$::jsonb,$q${"text":"The father of gods and men bore him far from men, hiding him from white-armed Hera.","src":"Homeric Hymn 1, trans. after Evelyn-White"}$q$::jsonb,$q$[{"n":"Anthesteria","when":"Anthesterion, roughly February","m":1},{"n":"City Dionysia","when":"Spring, in Athens","m":2}]$q$::jsonb) on conflict (deity_id) do update set line=excluded.line, sigil=excluded.sigil, quick=excluded.quick, invocation=excluded.invocation, altar=excluded.altar, altar_note=excluded.altar_note, upkeep=excluded.upkeep, large=excluded.large, reflect=excluded.reflect, hymn=excluded.hymn, festivals=excluded.festivals;
insert into public.pantheon_pairs values ($q$greek$q$,$q$hestia$q$,$q$hermes$q$,$q$The Homeric Hymn to Hestia pairs her with Hermes at the hearth's threshold: the settled and the mobile, asked to dwell in the house together.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheon_pairs values ($q$greek$q$,$q$apollo$q$,$q$dionysus$q$,$q$At Delphi, Apollo was said to leave each winter and hand the sanctuary to Dionysus: measured reason for three seasons, ecstasy for the fourth.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheon_pairs values ($q$greek$q$,$q$athena$q$,$q$hephaestus$q$,$q$The Chalceia was nominally their shared festival of craft, though the offering records name only Athena. The Hymn to Hephaestus has them teaching crafts together.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheon_pairs values ($q$greek$q$,$q$demeter$q$,$q$hades$q$,$q$Persephone binds them: Demeter's grief and Hades's pomegranate seed together make the turning of the seasons.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheon_pairs values ($q$greek$q$,$q$zeus$q$,$q$hera$q$,$q$The Daedala reenacted their quarrel and reconciliation, ending with heifers for Hera and bulls for Zeus.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheon_pairs values ($q$greek$q$,$q$ares$q$,$q$aphrodite$q$,$q$Their affair ended in Hephaestus's net, but it also produced Harmonia.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheon_pairs values ($q$greek$q$,$q$hephaestus$q$,$q$aphrodite$q$,$q$Husband and wife, whose marriage collapsed publicly after the net. Give them room on a shared altar.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheon_pairs values ($q$greek$q$,$q$athena$q$,$q$poseidon$q$,$q$Rivals for Athens: her olive tree beat his spring. The olive belongs to Athena, not to him.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheon_pairs values ($q$greek$q$,$q$apollo$q$,$q$artemis$q$,$q$Twins, children of Leto, born on Delos.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheon_pairs values ($q$greek$q$,$q$hestia$q$,$q$dionysus$q$,$q$The book's closing chapter: Dionysus came to fill the twelfth seat in later depictions as Hestia, who does not process, dropped out of them.$q$) on conflict (a,b) do update set text=excluded.text;
insert into public.pantheons (id,name,book,status,theme,rules,sort) values ($q$norse$q$,$q$Norse$q$,null,$q$planned$q$,null,null,1) on conflict (id) do update set name=excluded.name, book=excluded.book, status=excluded.status, theme=excluded.theme, rules=excluded.rules, sort=excluded.sort;
insert into public.pantheons (id,name,book,status,theme,rules,sort) values ($q$egyptian$q$,$q$Egyptian$q$,null,$q$planned$q$,null,null,2) on conflict (id) do update set name=excluded.name, book=excluded.book, status=excluded.status, theme=excluded.theme, rules=excluded.rules, sort=excluded.sort;
